import { useAudioPlayer } from "expo-audio";
import { useCallback } from "react";

// Generated by scripts/generate-trumpet-sounds.py.
const COMPLETION_SOUNDS = {
  pattern: require("../../assets/sounds/trumpet-pattern.wav"),
  session: require("../../assets/sounds/trumpet-session.wav"),
} as const;

export function useCompletionSound(kind: keyof typeof COMPLETION_SOUNDS) {
  const player = useAudioPlayer(COMPLETION_SOUNDS[kind], {
    downloadFirst: false,
    keepAudioSessionActive: false,
  });

  return useCallback(async () => {
    try {
      await player.seekTo(0);
      player.play();
    } catch (error) {
      console.warn("Efek suara tidak dapat diputar", error);
    }
  }, [player]);
}
